package com.group04.utils;
import static org.mockito.Mockito.*; import java.util.Optional; import org.junit.jupiter.api.Test; import org.springframework.boot.DefaultApplicationArguments; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import com.group04.dao.*; import com.group04.models.*;
class DataInitializerTest {
 @Test void initializationIsIdempotent()throws Exception{RoleRepository roles=mock(RoleRepository.class);AdminRepository admins=mock(AdminRepository.class);Role admin=new Role("ADMIN","Admin"),customer=new Role("CUSTOMER","Customer");when(roles.findByName("ADMIN")).thenReturn(Optional.of(admin));when(roles.findByName("CUSTOMER")).thenReturn(Optional.of(customer));when(admins.findByEmailIgnoreCase("admin@test.com")).thenReturn(Optional.of(new Admin(admin,"Admin","admin@test.com",null,"hash")));new DataInitializer(roles,admins,new BCryptPasswordEncoder(),"admin@test.com","Strong@123","Admin").run(new DefaultApplicationArguments(new String[0]));verify(roles,never()).save(any());verify(admins,never()).save(any());}
 @Test void createsMissingRolesAndAdminWithBcrypt()throws Exception{RoleRepository roles=mock(RoleRepository.class);AdminRepository admins=mock(AdminRepository.class);when(roles.findByName(anyString())).thenReturn(Optional.empty());when(roles.save(any())).thenAnswer(x->x.getArgument(0));when(admins.findByEmailIgnoreCase(anyString())).thenReturn(Optional.empty());new DataInitializer(roles,admins,new BCryptPasswordEncoder(4),"admin@test.com","Strong@123","Admin").run(new DefaultApplicationArguments(new String[0]));verify(roles,times(2)).save(any());verify(admins).save(argThat(a->a.getPasswordHash().startsWith("$2")&&!a.getPasswordHash().equals("Strong@123")));}
}

